-- DGFT & Customs: four combined questions split (DG01/DG09, DG03/DG10, DG04/DG11, DG07/DG12).
update public.hub_chk_points set q='Is the Import Export Code (IEC) active?', why='A de-activated IEC stops all shipments.', updated_at=now() where code='DG01';
update public.hub_chk_points set q='Is the bank AD code registered at every port we use?', why='Shipping bills cannot be filed otherwise.', updated_at=now() where code='DG03';
update public.hub_chk_points set q='Are shipping bills matched with bank realisation?', why='Unclaimed incentives are lost money.', updated_at=now() where code='DG04';
update public.hub_chk_points set q='Are bills of entry and duty payment proofs kept for every import?', why='Records can be audited for 5 years.', updated_at=now() where code='DG07';
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DG09','DGFT & Customs','Was the IEC updated this year, between April and June?','An IEC not updated each year can be de-activated.','Foreign Trade Policy 2023 para 2.05','exporter|importer',array[]::text[],'H','IEC update confirmation',7009,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DG10','DGFT & Customs','Is the ICEGATE login working?','Shipping bills cannot be filed otherwise.','Customs procedures','exporter|importer',array[]::text[],'M','ICEGATE login check',7010,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DG11','DGFT & Customs','Is RoDTEP / drawback claimed on every eligible shipment?','Unclaimed incentives are lost money.','FTP 2023; Customs Act s.75','exporter',array[]::text[],'M','RoDTEP / drawback claim sheet',7011,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DG12','DGFT & Customs','Are the required NOCs (CDSCO / BIS / FSSAI) kept for every import?','Records can be audited for 5 years.','Customs Act 1962 s.46; record rules','importer',array[]::text[],'H','NOC file',7012,true,null) on conflict (code) do nothing;
